package dev.starcore.starcore.module.treasury;

import static org.mockito.Mockito.*;
import dev.starcore.starcore.core.persistence.PersistenceService;
import dev.starcore.starcore.core.scheduler.StarCoreScheduler;
import dev.starcore.starcore.module.nation.model.NationId;
import java.math.BigDecimal;
import java.nio.file.*;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.atomic.*;
import java.util.logging.Logger;
import org.bukkit.plugin.java.JavaPlugin;

/** Diagnostic only: deliberately observes the outstanding budget interruption defect. */
public final class NavyBudgetInterruptionProbe {
  static final class InterruptedProcess extends Error {}
  public static void main(String[] args) throws Exception {
    Path directory = Path.of(args[0]);
    if (Files.exists(directory)) throw new IllegalStateException("Probe requires a new data directory");
    Files.createDirectories(directory);
    var plugin = mock(JavaPlugin.class);
    when(plugin.getDataFolder()).thenReturn(directory.toFile());
    when(plugin.getLogger()).thenReturn(Logger.getAnonymousLogger());
    var persistence = new PersistenceService(plugin, mock(StarCoreScheduler.class));
    persistence.start();
    try {
      var treasury = NavyTreasuryFixture.open(persistence, new AtomicInteger());
      var nation = NationId.random();
      treasury.deposit(nation, new BigDecimal("1000"));
      var files = new PersistenceBudgetStateStorage("navy-gap-probe", persistence);
      var crash = new AtomicBoolean();
      var storage = new BudgetStateStorage() {
        public Properties load() { return files.load(); }
        public void save(Properties values) {
          if (crash.getAndSet(false)) throw new InterruptedProcess();
          files.save(values);
        }
      };
      var budget = new BudgetServiceImpl(storage, treasury, treasury, Clock.systemUTC());
      String id = "navy:" + UUID.randomUUID();
      var request = new NationSpendingService.SpendRequest(id, nation, new BigDecimal("160"),
          NationSpendingService.SpendingCategory.MILITARY, "navy:CREATE:probe");
      crash.set(true);
      try { budget.spend(request); throw new AssertionError("Expected simulated interruption"); }
      catch (InterruptedProcess expected) {}
      var restartedTreasury = NavyTreasuryFixture.open(persistence, new AtomicInteger());
      var restartedBudget = new BudgetServiceImpl(files, restartedTreasury, restartedTreasury, Clock.systemUTC());
      var afterInterruption = restartedTreasury.balance(nation);
      boolean receiptMissing = restartedBudget.spendingReceipt(id).isEmpty();
      restartedBudget.spend(request);
      var afterRetry = restartedTreasury.balance(nation);
      var record = new LinkedHashMap<String, Object>();
      record.put("status", "KNOWN_CODE_GAP_REPRODUCED");
      record.put("mechanism", "Error before budget snapshot replacement simulates process interruption without RuntimeException compensation; both authorities then reconstructed from real files");
      record.put("starting_balance", "1000.00");
      record.put("purchase_amount", "160.00");
      record.put("balance_after_interruption", afterInterruption.toPlainString());
      record.put("original_budget_receipt_missing_after_restart", receiptMissing);
      record.put("balance_after_same_request_retry", afterRetry.toPlainString());
      record.put("expected_balance_after_single_purchase", "840.00");
      record.put("live_server_started", false);
      if (!receiptMissing || afterInterruption.compareTo(new BigDecimal("840")) != 0
          || afterRetry.compareTo(new BigDecimal("680")) != 0) throw new AssertionError(record);
      Files.writeString(Path.of(args[1]), new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(record) + "\n");
      System.out.println("Confirmed outstanding budget crash gap: 1000 -> 840 -> 680 for the same 160 request.");
    } finally { persistence.stop(); }
  }
}
